import{_ as t,o as e,c as o,ag as n}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年7月25日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-25.md","filePath":"science-log/src/reconstructed/2026-07-25.md"}'),a={name:"science-log/src/reconstructed/2026-07-25.md"};function s(g,r,i,l,c,h){return e(),o("div",null,[...r[0]||(r[0]=[n('<h1 id="🔬-科学快报-2026年7月25日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月25日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月25日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月25日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-07 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 检索说明：2026-07-25 为<strong>周六</strong>。CrossRef 按 <code>from-pub-date=until-pub-date=2026-07-25</code> 检索，<strong>Nature（0028-0836）命中 0 条、PNAS（0027-8424）命中 0 条、Science 前缀 10.1126 命中 0 条</strong>，即当日无研究论文出版。故科学 5 篇取自<strong>紧邻窗口（2026-07-22 ~ 2026-07-24）内的真实命中</strong>：PNAS 2026-07-22（1 篇）、PNAS 2026-07-23（2 篇）、Science Advances 2026-07-24（2 篇）。AI 5 篇严格取自 arXiv <code>submittedDate:[202607250000 TO 202607252359]</code> 的 cs.AI 真实条目（命中 30 篇）。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202607250000 TO 202607252359]</code>（cs.AI，30 条）+ EuropePMC / CrossRef 摘要核验 ｜ 重建日：2026-11-07</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-耐药性出现的那一刻-催化效率就掉了-一条持续数百万年的「活性—耐药」权衡" tabindex="-1">🧬 耐药性出现的那一刻，催化效率就掉了：一条持续数百万年的「活性—耐药」权衡 <a class="header-anchor" href="#🧬-耐药性出现的那一刻-催化效率就掉了-一条持续数百万年的「活性—耐药」权衡" aria-label="Permalink to &quot;🧬 耐药性出现的那一刻，催化效率就掉了：一条持续数百万年的「活性—耐药」权衡&quot;">​</a></h3><p><strong>An activity–resistance trade-off constrains enzyme evolution</strong><em>PNAS（2026-07-23）</em></p><p>抗生素产生菌为什么能先有「自我耐药基因」，再谈得上造出抗生素？这是微生物学里著名的先有鸡还是先有蛋。作者（Sarkis、Sørensen、Sondergaard、Nielsen、Frisvad 等）以霉酚酸（MPA，IMPDH 抑制剂）为模型：MPA 生物合成基因簇里带一个耐药版 IMPDH-B，而 IMPDH-B 的同源物广泛存在于<strong>不产 MPA 的真菌</strong>中，那里还留着基因簇残迹；IMPDH-B 的系统发育树与真菌物种树不一致，指向 Aspergillus 与 Sordariomycetes 之间的<strong>多次水平基因转移</strong>。他们表征了 11 个现存 IMPDH-B（5 个来自产生菌、6 个来自非产生菌）并<strong>复活了 7 个祖先酶（Anc1–Anc7）</strong>：耐药性出现在 Anc2 与 Anc3 之间，且<strong>恰好伴随催化效率下降</strong>；在祖先与现存酶合并的样本里，耐药性与活性降低强相关。意外的是这些酶同时对利巴韦林单磷酸（RVP）耐药——MPA 与 RVP 结合的是相似的酶构象，说明这条权衡很可能是「同时抵御多种抑制剂」这一设计约束的副产品。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2602068123" target="_blank" rel="noreferrer">10.1073/pnas.2602068123</a></p><h3 id="🌊-细胞分裂不只让组织长大-它还决定了上皮层流动的「普适几何」" tabindex="-1">🌊 细胞分裂不只让组织长大，它还决定了上皮层流动的「普适几何」 <a class="header-anchor" href="#🌊-细胞分裂不只让组织长大-它还决定了上皮层流动的「普适几何」" aria-label="Permalink to &quot;🌊 细胞分裂不只让组织长大，它还决定了上皮层流动的「普适几何」&quot;">​</a></h3><p><strong>Cell division sets a universal flow geometry in cell layers</strong><em>PNAS（2026-07-22）</em></p><p>上皮组织的集体流动里有一套几何骨架：涡旋状界面，其统计呈现<strong>临界渗流与共形不变性</strong>的特征——也就是说，这群细胞在某种意义上是「尺度无关」的。但什么基本细胞过程在维持这种对称性丰富的几何，此前没人说清。作者（Ma、Bonn、Grudtsyna、Abbasova、Pedersen 等）用<strong>两种独立的药理手段抑制增殖</strong>：相干流动依然存在，但<strong>邻居交换减少、共形不变的几何消失了</strong>；而阻断凋亡不影响普适性，从而把「分裂」单独锁定为控制变量。一个<strong>分裂速率可调的顶点模型（vertex model）<strong>定量复现了这些效应，并证明只要允许分裂，共形不变性就回来。机制上，分裂相当于</strong>间歇性的拓扑更新</strong>，它不断「松开」细胞—细胞网络的约束，使网络保持跨尺度重排的柔性。分裂因此不只是生长，而是集体自组织的结构与力学调节器。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2532420123" target="_blank" rel="noreferrer">10.1073/pnas.2532420123</a></p><h3 id="🧠-谱半径大于-1-也不炸-除法归一化给递归网络上了「稳定器」" tabindex="-1">🧠 谱半径大于 1 也不炸：除法归一化给递归网络上了「稳定器」 <a class="header-anchor" href="#🧠-谱半径大于-1-也不炸-除法归一化给递归网络上了「稳定器」" aria-label="Permalink to &quot;🧠 谱半径大于 1 也不炸：除法归一化给递归网络上了「稳定器」&quot;">​</a></h3><p><strong>Stabilization of recurrent neural networks through divisive normalization</strong><em>PNAS（2026-07-23）</em></p><p>线性递归网络的稳定性判据很苛刻：递归矩阵的所有特征值必须落在单位圆内，谱半径稍过 1 就发散——这意味着稳定性对突触权重的精确取值极度敏感，而真实皮层显然不是这样精密调参出来的。作者（Morone、Rawat、Heeger、Martiniani）从理论与数值两方面证明：<strong>只要网络包含除法归一化（divisive normalization）</strong>——那个抑制单个神经元响应的动力学操作——<strong>任意递归网络即使在谱半径超过 1 时仍可保持稳定</strong>。递归权重足够强时终究会失稳，但失稳之前会先进入<strong>临界慢化（critical slowing down）<strong>区间，而临界慢化的起点</strong>恰好等于归一化失效的临界点</strong>，他们给出了该临界点随突触强度与外部输入幅度的解析预测。这为「归一化在神经系统中为何如此普遍」提供了一个动力学答案：它是强递归下稳定性的必要条件。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2601841123" target="_blank" rel="noreferrer">10.1073/pnas.2601841123</a></p><h3 id="🧲-寒武纪大爆发之后-地磁场又弱了-4000-万年" tabindex="-1">🧲 寒武纪大爆发之后，地磁场又弱了 4000 万年 <a class="header-anchor" href="#🧲-寒武纪大爆发之后-地磁场又弱了-4000-万年" aria-label="Permalink to &quot;🧲 寒武纪大爆发之后，地磁场又弱了 4000 万年&quot;">​</a></h3><p><strong>Earth&#39;s magnetic field remained weak for 40 million years after the Cambrian radiation</strong><em>Science Advances（2026-07-24）</em></p><p>埃迪卡拉纪—寒武纪是地球环境剧变与复杂动物出现的窗口，而这段时期恰好包含地球史上最弱的磁场强度。曾有假说认为<strong>内核成核</strong>发生在这一界线附近，触发早寒武世地磁发电机快速增强；但跨该区间的直接磁场约束一直很少。作者（Lloyd、Biggin、Hopkins、Tully、Cych、Paterson、Trindade）在巴西（约 <strong>5.25 亿年前</strong>）与新斯科舍（约 <strong>5.05 亿年前</strong>）两条寒武纪火成岩序列上做<strong>古强度</strong>测量，用多种互补方法交叉验证：两处记录都显示一个<strong>正在倒转但持续偏弱</strong>的地磁场。叠加对已发表数据的再分析，结论是弱磁场状态在寒武纪生命大辐射之后<strong>又延续了数千万年</strong>，这限定了任何「寒武纪发电机增强」事件的幅度与时间，也意味着早期动物演化关键阶段的<strong>磁层屏蔽处于强抑制状态</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aeg2325" target="_blank" rel="noreferrer">10.1126/sciadv.aeg2325</a></p><h3 id="🔋-「螺旋土豆」形-cof-把锌沉积掰成近单向-做出-156-wh-kg-水系软包" tabindex="-1">🔋 「螺旋土豆」形 COF：把锌沉积掰成近单向，做出 156 Wh/kg 水系软包 <a class="header-anchor" href="#🔋-「螺旋土豆」形-cof-把锌沉积掰成近单向-做出-156-wh-kg-水系软包" aria-label="Permalink to &quot;🔋 「螺旋土豆」形 COF：把锌沉积掰成近单向，做出 156 Wh/kg 水系软包&quot;">​</a></h3><p><strong>Spiral-potato-like nanostructure COF enabling nearly unidirectional zinc deposition for Ah-level pouch cells</strong><em>Science Advances（2026-07-24）</em></p><p>水系锌离子电池要上安时级，难点是同时要<strong>高锌利用率</strong>与<strong>均匀成核/生长</strong>——枝晶一起，利用率就上不去。作者（Duan、Li、Wu、Chen、Zeng 等）合成了一种<strong>螺旋土豆状共价有机框架（SP-COF）<strong>纳米结构，用它构建</strong>各向同性固体电解质界面</strong>：相比常规 COF 形貌，这种卷曲形貌带来的亲和位点与孔隙率使界面调控各向同性，锌沉积<strong>沿着理论三维成核曲线近单向生长</strong>。性能上：SP-COF/Zn 对称电池在 <strong>10 mA/cm²</strong> 下稳定镀/剥 <strong>2800 小时</strong>；三层层叠的安时级软包（SP-COF/Zn‖I₂，<strong>1.2 Ah</strong>）循环 <strong>200 圈</strong>稳定，锌利用率高达 <strong>40%</strong>，能量密度达到 <strong>156 Wh/kg</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aeg5141" target="_blank" rel="noreferrer">10.1126/sciadv.aeg5141</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🛡️-用「共识」防投毒-多教师蒸馏压掉潜意识学习" tabindex="-1">🛡️ 用「共识」防投毒：多教师蒸馏压掉潜意识学习 <a class="header-anchor" href="#🛡️-用「共识」防投毒-多教师蒸馏压掉潜意识学习" aria-label="Permalink to &quot;🛡️ 用「共识」防投毒：多教师蒸馏压掉潜意识学习&quot;">​</a></h3><p><strong>Defense via Consensus: Mitigating Subliminal Learning through Multi-Teacher Distillation</strong><em>arXiv（2026-07-25）</em></p><p>微调会引入意外行为——可能是刻意投毒，也可能是从看似无害的数据里泛化出来的「潜意识学习」（subliminal learning）。作者（Narang、Tajdini、Zhang、Morgenstern）的出发点是：<strong>为同一任务独立收集的数据集，会共享意图能力而携带不同的意外效应</strong>。据此提出 <strong>MSCD（Multi-Source Consensus Distillation）</strong>：每个数据集各微调一个模型，用这些模型之间的<strong>一致意见</strong>生成替代训练响应，再让一个全新的学生模型在这些响应上训练；并给出最小规则与基相对（base-relative）规则两种聚合方式，扩展到「只有部分模型学到」或「表达措辞不同」的情形。在受控投毒、潜意识学习、涌现性失对齐三类实验中，该方法压制了不想要的行为同时保住了共享收益；在一个实用的语言理解任务里，MSCD 保留了意图分类能力，并减少了微调过程中被带进来的<strong>不安全医疗建议</strong>。核心逻辑很朴素：单源的「怪癖」不共识，就蒸馏不掉。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.23394" target="_blank" rel="noreferrer">2607.23394</a></p><h3 id="⚖️-置信地错-嵌套规则下的「例外链崩塌」" tabindex="-1">⚖️ 置信地错：嵌套规则下的「例外链崩塌」 <a class="header-anchor" href="#⚖️-置信地错-嵌套规则下的「例外链崩塌」" aria-label="Permalink to &quot;⚖️ 置信地错：嵌套规则下的「例外链崩塌」&quot;">​</a></h3><p><strong>Confidently Wrong: Exception Chain Collapse in Frontier LLM Rule Evaluation</strong><em>arXiv（2026-07-25）</em></p><p>作者（Simpson、Kozak、Doake）记录了一类前沿模型在<strong>资格判定</strong>上的失败模式，命名为 <strong>exception chain collapse</strong>：规则形如「A 必需，<strong>除非</strong>适用 B，<strong>除非</strong> C 覆盖 B」，链条一长模型就开始自信地判错。更麻烦的是它的经验表面不稳定——2026 年 3 月至 4 月间，多个失败单元在<strong>同一模型别名下静默闭合</strong>（GPT-5.4 在建筑保险场景从 96.6% 升到 100%，提示词与测试框架完全相同、无版本号变更）。对受监管流程来说，这意味着前沿模型的准确率是一条<strong>会无声漂移的合规边界</strong>。他们的对策是神经—符号拆分：<strong>Aethis Eligibility Module</strong> 让 LLM 只负责从权威来源撰写规则，具体执行交给 <strong>SMT 求解层</strong>确定性地跑。证据有三块：跨四个监管域、<strong>225 个场景</strong>的受控基准；20 场景对抗扩展（构造保险）上引擎 <strong>20/20</strong>，而四种前沿配置里只有一种（低推理强度 GPT-5.4）同样满分。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.23386" target="_blank" rel="noreferrer">2607.23386</a></p><h3 id="🚫-clip「知道否定-但说不出口」-从冻结中间层把语法捞回来" tabindex="-1">🚫 CLIP「知道否定，但说不出口」：从冻结中间层把语法捞回来 <a class="header-anchor" href="#🚫-clip「知道否定-但说不出口」-从冻结中间层把语法捞回来" aria-label="Permalink to &quot;🚫 CLIP「知道否定，但说不出口」：从冻结中间层把语法捞回来&quot;">​</a></h3><p><strong>What CLIP Knows but Cannot Say: Recovering Negation from Frozen Intermediate Features</strong><em>arXiv（2026-07-25）</em></p><p>CLIP 把「一只狗」与「不是一只狗」映射到几乎相同的嵌入，对否定近乎失明。作者（Lu、Chen、Chaterji）把病因命名为 <strong>Representational Collapse</strong>：逐层追踪组合分歧与视觉对齐度后发现，<strong>中间层确实构建了组合语法</strong>，但后层在视觉对齐度上升的同时把这层结构<strong>压平</strong>了，最终表征「语法盲」。他们提出 <strong>PeakPatch</strong>：不改任何预训练权重，在<strong>组合峰值层</strong>截取信号——嵌入校正网络（ECN）用交叉注意力提取否定特异信号、锚定到稳定基线，预测一个偏差向量把它重新注入末层嵌入空间；配套的分数校正网络（SCN）为判别任务预测有界的标量偏移。两模块端到端联合训练、CLIP 全部冻结，只增加 <strong>5.2M 参数（骨干的 3.5%）</strong>，保留标准余弦相似度接口；在 NegBench 上取得提升。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.23271" target="_blank" rel="noreferrer">2607.23271</a></p><h3 id="📈-训练之前先预测-粒子物理基础模型的缩放定律可以外推" tabindex="-1">📈 训练之前先预测：粒子物理基础模型的缩放定律可以外推 <a class="header-anchor" href="#📈-训练之前先预测-粒子物理基础模型的缩放定律可以外推" aria-label="Permalink to &quot;📈 训练之前先预测：粒子物理基础模型的缩放定律可以外推&quot;">​</a></h3><p><strong>Predict before you train: Scaling Laws for particle physics foundation models</strong><em>arXiv（2026-07-25）</em></p><p>粒子物理里最大的模型也是最贵的，但在算力花出去之前没人能估计「再放大一档」的回报。作者（Uslu、Nachman、Ré）证明这件事可以对撞机喷注上的通用 Transformer 做到：<strong>只用小模型拟合</strong>一个模型—数据联合缩放定律（覆盖三个数量级的训练算力），就能把之后用<strong>一百倍以上算力</strong>训练出的模型的 loss 预测到 <strong>1% 以内</strong>。他们进一步把预测接到下游物理性能：在两个标准喷注标记基准上，预训练 loss 越低，微调后的 loss 系统性越低、背景拒绝率越高。于是在这个模型族与这批任务范围内，<strong>算力预算可以在训练之前被换算成预期的物理性能</strong>；最终的前沿模型在准确率、AUC、夸克/胶子拒绝率上与已发表的物理感知基础模型一致，后者仅在高纯度尾部略有优势。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.23377" target="_blank" rel="noreferrer">2607.23377</a></p><h3 id="🎯-单层自注意力的前向传播-就是一次无悔学习更新" tabindex="-1">🎯 单层自注意力的前向传播，就是一次无悔学习更新 <a class="header-anchor" href="#🎯-单层自注意力的前向传播-就是一次无悔学习更新" aria-label="Permalink to &quot;🎯 单层自注意力的前向传播，就是一次无悔学习更新&quot;">​</a></h3><p><strong>Training with (Swap) Regret Loss in a Single-Layer Self-Attention Model: A Case Study on the Probability Simplex</strong><em>arXiv（2026-07-25）</em></p><p>作者（Park、Ozdaglar）从概率单纯形上的策略视角，重新审视把<strong>决策论后悔（regret）当作直接损失函数</strong>来训练模型的框架。第一个结果：用 regret loss 训练的<strong>单层自注意力模型</strong>存在一个驻点，其前向传播恰好等于带合适步长的<strong>平滑虚拟对局（smoothed fictitious play）</strong>——也就是保证无悔行为的那个更新，给定任意策略输入，模型输出的就是虚拟对局会给出的更新。第二个结果是新的 <strong>swap-regret loss</strong>，把框架从外部后悔推进到「互换偏差」鲁棒性：该损失同样有驻点，其前向实现经典 Blum–Mansour 无通道实现算法诱导的 swap-regret 更新，且<strong>每个注意力头各实现一次外部后悔更新</strong>。这把「注意力头在学什么」翻译成了博弈论语言：一排头 = 一排无悔学习器。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.23333" target="_blank" rel="noreferrer">2607.23333</a></p><blockquote><p>📅 日期：2026-07-25 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const u=t(a,[["render",s]]);export{d as __pageData,u as default};
